using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using Object=UnityEngine.Object;

public static class OutdoorRainPass
{
 const string ScenePath="Assets/Scenes/3D/RecoilPrototype.unity",Folder="Assets/Recoil3D/OutdoorRain",Marker="Outdoor rain - camera local low budget particles";
 static T[] All<T>(Scene s)where T:Component{return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();}
 static Material Material(string name,bool splash){var path=Folder+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Recoil/3D/Low Cost Local Rain"));m.name=name;AssetDatabase.CreateAsset(m,path);}m.SetColor("_Tint",splash?new Color(.46f,.52f,.53f,1):new Color(.56f,.64f,.68f,1));m.SetFloat("_Splash",splash?1:0);EditorUtility.SetDirty(m);return m;}
 static ParticleSystem CreateSystem(Transform root,string name,Material material,bool splash)
 {
  var g=new GameObject(name);g.transform.SetParent(root,false);var p=g.AddComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);p.useAutoRandomSeed=false;p.randomSeed=splash?1947u:1978u;
  var main=p.main;main.loop=true;main.duration=3;main.prewarm=true;main.playOnAwake=false;main.simulationSpace=ParticleSystemSimulationSpace.World;main.scalingMode=ParticleSystemScalingMode.Local;main.cullingMode=ParticleSystemCullingMode.AlwaysSimulate;main.maxParticles=splash?64:1000;main.startLifetime=splash?new ParticleSystem.MinMaxCurve(.30f,.43f):new ParticleSystem.MinMaxCurve(.9f,1.2f);main.startSpeed=0;main.gravityModifier=0;main.startSize=splash?new ParticleSystem.MinMaxCurve(.075f,.17f):new ParticleSystem.MinMaxCurve(.011f,.019f);main.startColor=splash?new ParticleSystem.MinMaxGradient(new Color(1,1,1,.10f),new Color(1,1,1,.18f)):new ParticleSystem.MinMaxGradient(new Color(1,1,1,.16f),new Color(1,1,1,.26f));
  var emission=p.emission;emission.enabled=true;emission.rateOverTime=splash?32:650;var shape=p.shape;shape.enabled=true;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=splash?new Vector3(30,.001f,10.2f):new Vector3(30,1.6f,20);
  var velocity=p.velocityOverLifetime;velocity.enabled=!splash;velocity.space=ParticleSystemSimulationSpace.World;velocity.x=1.25f;velocity.y=-16.5f;velocity.z=.18f;
  var colour=p.colorOverLifetime;colour.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},splash?new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(1,.1f),new GradientAlphaKey(0,1)}:new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(1,.08f),new GradientAlphaKey(1,.85f),new GradientAlphaKey(0,1)});colour.color=gradient;
  var size=p.sizeOverLifetime;size.enabled=splash;size.size=new ParticleSystem.MinMaxCurve(1,AnimationCurve.Linear(0,.25f,1,1.4f));var collision=p.collision;collision.enabled=false;var noise=p.noise;noise.enabled=false;var trails=p.trails;trails.enabled=false;var lights=p.lights;lights.enabled=false;var sub=p.subEmitters;sub.enabled=false;
  var renderer=p.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=material;renderer.renderMode=splash?ParticleSystemRenderMode.HorizontalBillboard:ParticleSystemRenderMode.Stretch;renderer.velocityScale=splash?0:.018f;renderer.lengthScale=1.4f;renderer.cameraVelocityScale=0;renderer.sortMode=ParticleSystemSortMode.None;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;renderer.lightProbeUsage=LightProbeUsage.Off;renderer.reflectionProbeUsage=ReflectionProbeUsage.Off;renderer.motionVectorGenerationMode=MotionVectorGenerationMode.ForceNoMotion;renderer.minParticleSize=0;renderer.maxParticleSize=.08f;
  return p;
 }
 static Bounds Roof(float minX,float maxX,float minZ,float maxZ,float top){return new Bounds(new Vector3((minX+maxX)*.5f,top*.5f,(minZ+maxZ)*.5f),new Vector3(maxX-minX,top,maxZ-minZ));}
 public static string Apply()
 {
  if(EditorApplication.isPlayingOrWillChangePlaymode)return "Playing; apply deferred";Directory.CreateDirectory(Folder);Directory.CreateDirectory("Backups/OutdoorRain");Directory.CreateDirectory("output/outdoor-rain");var previous=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath(ScenePath);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);
  try{if(All<RecoilOutdoorRain>(scene).Length>0)return "Outdoor rain already installed";var backup="Backups/OutdoorRain/"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-RecoilPrototype.unity";EditorSceneManager.SaveScene(scene,backup,true);var collisions=All<Collider2D>(scene).Select(c=>c.GetInstanceID()+"|"+c.bounds+"|"+c.enabled).ToArray();var doors=All<RecoilDoor>(scene).Select(d=>EditorJsonUtility.ToJson(d)+"|"+d.transform.position).ToArray();
   var g=new GameObject(Marker);SceneManager.MoveGameObjectToScene(g,scene);g.transform.SetParent(All<RecoilPrototype>(scene).Single().transform,false);var weather=g.AddComponent<RecoilOutdoorRain>();weather.sceneCamera=All<Camera>(scene).Single(c=>c.CompareTag("MainCamera"));weather.rain=CreateSystem(g.transform,"Rain streaks - max 1000 world-space drops",Material("Unlit thin rain streaks",false),false);weather.splashes=CreateSystem(g.transform,"Sparse ground impact rings - max 64",Material("Unlit sparse ground rain rings",true),true);
   var roofs=new List<Bounds>{Roof(-16.48f,-4.08f,.58f,21.7f,4.48f),Roof(74.12f,106.52f,2.84f,36,19.8f),Roof(109.82f,140.82f,.41f,31.5f,7.2f)};
   foreach(var r in All<MeshRenderer>(scene).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&(r.name=="Solid flat roof"||r.name=="Canopy flat roof"||r.name=="Projecting roof cornice"))){var b=r.bounds;if(b.size.x<3||b.size.z<2)continue;bool covered=roofs.Any(old=>b.center.x>=old.min.x&&b.center.x<=old.max.x&&b.center.z>=old.min.z&&b.center.z<=old.max.z);if(!covered)roofs.Add(Roof(b.min.x,b.max.x,b.min.z,b.max.z,b.max.y));}
   weather.shelters=roofs.Take(16).ToArray();weather.ApplyShelters();weather.PositionForCamera(weather.sceneCamera);weather.StopAndClear();EditorUtility.SetDirty(weather);
   if(!collisions.SequenceEqual(All<Collider2D>(scene).Select(c=>c.GetInstanceID()+"|"+c.bounds+"|"+c.enabled)))throw new Exception("Rain changed collision");if(!doors.SequenceEqual(All<RecoilDoor>(scene).Select(d=>EditorJsonUtility.ToJson(d)+"|"+d.transform.position)))throw new Exception("Rain changed door state");if(g.GetComponentsInChildren<Collider>().Length+g.GetComponentsInChildren<Light>().Length>0)throw new Exception("Weather should contain no colliders or lights");
   EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();string result="PASS installed outdoor-only camera-local rain: 2 Shuriken systems, single-pass unlit alpha shader, hard limits 1000 streaks + 64 impact rings, world-space falling motion, no collision/shadows/particle lights/subemitters. "+weather.shelters.Length+" cheap roof footprint masks. Existing geometry, Collider2D and door state unchanged. Backup="+backup;File.WriteAllText("output/outdoor-rain/installation.txt",result);return result;
  }finally{if(opened)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(previous);var world=All<Recoil3DWorld>(previous).FirstOrDefault();if(world)world.ApplyAtmosphere();var look=All<WarehouseAtmosphereTest>(previous).FirstOrDefault();if(look)look.ApplyLook();}
 }
 static void Shot(Camera camera,string name){typeof(FactoryRoofStairHeadPass).GetMethod("Shot",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{camera,name});Directory.CreateDirectory("Captures/OutdoorRain");File.Copy("Captures/FactoryRoofStairHead/"+name+".png","Captures/OutdoorRain/"+name+".png",true);}
 public static string VerifyAndCapture()
 {
  if(EditorApplication.isPlayingOrWillChangePlaymode)return "Playing; verification deferred";var previous=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath(ScenePath);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);var others=Enumerable.Range(0,SceneManager.sceneCount).Select(SceneManager.GetSceneAt).Where(s=>s!=scene).ToArray();var rs=others.SelectMany(All<Renderer>).Where(r=>r.enabled).ToArray();var ls=others.SelectMany(All<Light>).Where(l=>l.enabled).ToArray();GameObject cg=null;RecoilOutdoorRain weather=null;
  try{foreach(var r in rs)r.enabled=false;foreach(var l in ls)l.enabled=false;SceneManager.SetActiveScene(scene);All<Recoil3DWorld>(scene).First().ApplyAtmosphere();weather=All<RecoilOutdoorRain>(scene).Single();cg=new GameObject("Temporary outdoor rain verification camera");var camera=cg.AddComponent<Camera>();camera.fieldOfView=36;camera.nearClipPlane=.1f;camera.farClipPlane=180;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.03f,.035f);camera.transform.position=new Vector3(126,4,-19.5f);camera.transform.LookAt(new Vector3(127,2.8f,2.7f));
   weather.StopAndClear();Shot(camera,"FactoryBeforeRain");weather.Preview(camera,3.2f);if(weather.rain.particleCount==0||weather.rain.particleCount>1000||weather.splashes.particleCount>64)throw new Exception("Particle count outside budget");int normalDrops=weather.rain.particleCount,normalImpacts=weather.splashes.particleCount;Shot(camera,"FactoryLocalRain");
   weather.density=2;weather.Preview(camera,8);if(weather.rain.particleCount>1000||weather.splashes.particleCount>64)throw new Exception("Maximum density exceeds budget");int stress=weather.rain.particleCount;weather.density=1;
   camera.transform.position=new Vector3(-42,3,-16);camera.transform.LookAt(new Vector3(-42,2.3f,3));camera.fieldOfView=43;weather.Preview(camera,3.2f);Shot(camera,"ForecourtRoofShelteredRain");
   camera.transform.position=new Vector3(98,15,-22);camera.transform.LookAt(new Vector3(99,11,3));weather.Preview(camera,3.2f);Shot(camera,"FactoryUpperViewRain");
   var renderer=weather.rain.GetComponent<ParticleSystemRenderer>();if(renderer.shadowCastingMode!=ShadowCastingMode.Off||renderer.sharedMaterial.passCount!=1||weather.rain.collision.enabled||weather.splashes.collision.enabled)throw new Exception("Expensive particle features unexpectedly enabled");
   string report="PASS normal simulation: "+normalDrops+" drops and "+normalImpacts+" impact rings; 2x-density 8s simulation: "+stress+" drops, within 1000/64 hard caps. 2 renderers, each material 1 unlit pass; no particle collision, shadows, lights, trail/sub-emitter modules. Factory street, petrol canopy shelter and elevated camera views rendered. GPU/CPU frame time was not benchmarked. No scene changes saved during capture.";File.WriteAllText("output/outdoor-rain/verification.txt",report);return report;
  }finally{if(weather){weather.density=1;weather.StopAndClear();}if(cg)Object.DestroyImmediate(cg);foreach(var r in rs)if(r)r.enabled=true;foreach(var l in ls)if(l)l.enabled=true;if(opened)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(previous);var world=All<Recoil3DWorld>(previous).FirstOrDefault();if(world)world.ApplyAtmosphere();var look=All<WarehouseAtmosphereTest>(previous).FirstOrDefault();if(look)look.ApplyLook();}
 }
